function captcha_valid(string $answer): bool{$challenge=$_SESSION['school_captcha']??null;unset($_SESSION['school_captcha']);return is_array($challenge)&&time()-$challenge['time']<=180&&hash_equals($challenge['hash'],hash('sha256',strtoupper(trim(ascii_digits($answer)))));}
function audit_event(?array $u,string $action,string $target='',string $outcome='success',string $details=''): void{try{$q=db()->prepare('INSERT INTO pdm_audit_events(actor_id,actor_key,action,target,outcome,ip_hash,details) VALUES(?,?,?,?,?,?,?)');$q->execute([$u['id']??null,$u?school_actor($u):'anonymous',$action,mb_substr($target,0,160),$outcome,hash('sha256',($_SERVER['REMOTE_ADDR']??'').($_SERVER['HTTP_USER_AGENT']??'')),mb_substr($details,0,1000)]);}catch(Throwable $e){error_log('Audit write failed');}}
function automatic_backups(PDO $db,array $snapshot,int $revision,int $actorId): void{$keys=['daily'=>date('Y-m-d'),'weekly'=>date('o-W'),'monthly'=>date('Y-m'),'yearly'=>date('Y')];$payload=json_encode(school_wire($snapshot),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$q=$db->prepare('INSERT IGNORE INTO pdm_school_backups(kind,period_key,revision,actor_id,payload) VALUES(?,?,?,?,?)');foreach($keys as $kind=>$key)$q->execute([$kind,$key,$revision,$actorId,$payload]);$limits=['daily'=>14,'weekly'=>8,'monthly'=>12,'yearly'=>5];foreach($limits as $kind=>$limit){$del=$db->prepare('DELETE FROM pdm_school_backups WHERE kind=? AND id NOT IN (SELECT id FROM (SELECT id FROM pdm_school_backups WHERE kind=? ORDER BY id DESC LIMIT '.$limit.') kept)');$del->execute([$kind,$kind]);}}
